import { initTRPC, TRPCError } from "@trpc/server";
import superjson from "superjson";

export interface Context {
  /** Generated by the app on first launch and sent as `x-kip-user`. No accounts for the hackathon. */
  userId: string | null;
}

export function createContext({ req }: { req: Request }): Context {
  return { userId: req.headers.get("x-kip-user") };
}

const t = initTRPC.context<Context>().create({ transformer: superjson });

export const router = t.router;
export const createCallerFactory = t.createCallerFactory;
export const publicProcedure = t.procedure;

/** Procedures that need a user ID. */
export const userProcedure = t.procedure.use(({ ctx, next }) => {
  if (!ctx.userId) throw new TRPCError({ code: "UNAUTHORIZED", message: "Missing x-kip-user" });
  return next({ ctx: { userId: ctx.userId } });
});
EOF
