  seed = (seed * 1664525 + 1013904223) % 2 ** 32;
  return seed / 2 ** 32;
};
const round1 = (n: number) => Math.round(n * 10) / 10;

const start = Date.parse("2026-11-13T23:00:00Z"); // Friday 23:00 GMT
const seconds = 8 * 60 * 60;
const t0 = start / 1000;
